var n=`1142-pumpkin-pie`;var a=`world-1142`;var t=`US`;var r=`northern-america`;var o=8;var s=156;var d={en:`Pumpkin Pie`,ua:`Гарбузовий пиріг`};var u={en:`Pumpkin Pie is a dish from United States prepared with all-purpose flour, canned pumpkin purée, evaporated milk, chicken egg. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Гарбузовий пиріг, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: пшеничне борошно універсальне, консервоване гарбузове пюре, концентроване молоко без цукру, куряче яйце. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var p=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,300,`g`],[`unsalted-butter`,160,`g`],[`water`,90,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`canned-pumpkin-puree`,560,`g`],[`evaporated-milk`,420,`ml`],[`chicken-egg`,3,`pcs`],[`brown-sugar`,145,`g`],[`pumpkin-pie-spice`,12,`g`]]},{en:`Layer the already prepared filling and base evenly in the baking dish or pan.`,ua:`Рівномірно викладіть уже підготовлені основу й начинку шарами у форму чи на деко.`,t:[`layered-assembly`],m:6,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 50 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 50 хвилин до готовності.`,t:[`baking`],m:50,i:[]},{en:`Refrigerate the prepared mixture for about 70 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 70 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:70,i:[]}];var l={slug:n,id:a,country:`US`,region:r,servings:8,minutes:156,title:d,text:u,steps:p};export{t as country,l as default,a as id,s as minutes,r as region,o as servings,n as slug,p as steps,u as text,d as title};